'use client'
import { useState } from 'react'
export default function VendorControls({ vendorId, status }: { vendorId: string; status: string }) {
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState('')
  async function act(action: string) { const reason = action === 'reject' || action === 'suspend' ? window.prompt('Reason')?.trim() : undefined; if ((action === 'reject' || action === 'suspend') && !reason) return; setBusy(true); setMessage(''); try { const r = await fetch(`/api/admin/vendors/${vendorId}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action, reason }) }); const d = await r.json(); if (!r.ok) throw new Error(d.error || 'Operation failed'); window.location.reload() } catch (e) { setMessage(e instanceof Error ? e.message : 'Operation failed') } finally { setBusy(false) } }
  return <div className="rounded-xl border bg-background p-4"><h2 className="font-semibold">Vendor moderation</h2><p className="mt-1 text-xs text-muted-foreground">Current status: {status}. Changes are audited.</p><div className="mt-4 flex flex-wrap gap-2">{status !== 'APPROVED' && <button disabled={busy} onClick={() => void act('approve')} className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Approve</button>}{status !== 'REJECTED' && <button disabled={busy} onClick={() => void act('reject')} className="rounded-lg border px-4 py-2 text-sm">Reject</button>}{status !== 'SUSPENDED' && <button disabled={busy} onClick={() => void act('suspend')} className="rounded-lg border px-4 py-2 text-sm">Suspend</button>}{status === 'SUSPENDED' && <button disabled={busy} onClick={() => void act('reactivate')} className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Reactivate</button>}</div>{message && <p className="mt-3 text-sm text-destructive">{message}</p>}</div>
}
